<?php require_once __DIR__.'/../functions.php'; init_db(); require_login();$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{$path=save_upload('media');if(!$path)throw new RuntimeException('Bitte eine Datei auswählen.');$msg='Upload erfolgreich: '.$path;}catch(Throwable $e){$err=$e->getMessage();}}$files=[];$dir=UPLOAD_DIR;if(is_dir($dir)){foreach(scandir($dir) as $f){if($f==='.'||$f==='..')continue;$files[]='uploads/'.$f;}}?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Medien – Young Images</title><link rel="stylesheet" href="../css/admin.css"></head><body><div class="admin-shell"><aside><img src="../assets/young-images-logo.png" class="admin-logo"><nav><a href="index.php">Dashboard</a><a class="sel" href="media.php">Medien / Upload</a><a href="settings.php">Einstellungen</a><a href="../index.php" target="_blank">Website ansehen ↗</a><a href="logout.php">Abmelden</a></nav></aside><main class="admin-main"><div class="admin-head"><div><div class="eyebrow">MEDIENBIBLIOTHEK</div><h1>Bilder hochladen</h1></div></div><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="error"><?=e($err)?></div><?php endif;?><section class="panel"><h2>Neues Bild hochladen</h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="file" name="media" accept="image/jpeg,image/png,image/webp,image/gif,application/pdf" required><button>Hochladen</button></form><p class="hint">Erlaubt: JPG, PNG, WEBP, GIF oder PDF · maximal 12 MB. Nach dem Upload erscheint der Pfad. Diesen kannst du im jeweiligen Eintrag in das Feld „Bildpfad“ kopieren.</p></section><section class="panel"><h2>Vorhandene Uploads</h2><div class="media-grid"><?php foreach(array_reverse($files) as $f):?><div class="media-item"><?php if(preg_match('/\.(jpe?g|png|webp|gif)$/i',$f)):?><img src="../<?=e($f)?>" alt=""><?php else:?><div class="pdf">PDF</div><?php endif;?><code><?=e($f)?></code></div><?php endforeach;?></div></section></main></div></body></html>
